// Meta calls this once when you subscribe the webhook.
const q = $input.first().json.query ?? {};
if (q['hub.verify_token'] !== $env.META_VERIFY_TOKEN) {
  throw new Error('verify token mismatch');
}
return [{ json: { challenge: q['hub.challenge'] } }];

// Reject anything not signed with the Meta app secret. Without this,
// anyone who learns the URL can inject fake customers into the CRM.
const crypto = require('crypto');
const item = $input.first();

const raw = item.binary?.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : JSON.stringify(item.json.body);

const expected = 'sha256=' + crypto
  .createHmac('sha256', $env.META_APP_SECRET)
  .update(raw, 'utf8')
  .digest('hex');

const received = item.json.headers['x-hub-signature-256'];
if (!received || received !== expected) {
  throw new Error('invalid signature');
}

return [{ json: { body: JSON.parse(raw) } }];

// Flatten Messenger and Instagram into one shape, and drop everything
// that is not a real inbound message.
const body = $input.first().json.body;
const out = [];

for (const entry of body.entry ?? []) {
  for (const ev of entry.messaging ?? []) {
    if (ev.message?.is_echo) continue;          // our own message coming back
    if (!ev.message && !ev.postback) continue;  // reads, deliveries, reactions

    const referral = ev.referral ?? ev.postback?.referral ?? {};

    out.push({ json: {
      page_id:     entry.id,
      platform:    body.object === 'instagram' ? 'instagram' : 'messenger',
      sender_id:   ev.sender.id,
      message_id:  ev.message?.mid ?? `pb_${ev.sender.id}_${ev.timestamp}`,
      text:        ev.message?.text ?? ev.postback?.title ?? '',
      has_media:   Boolean(ev.message?.attachments?.length),
      // Only present on the first message of an ad-driven thread. If it is
      // not captured here, ad attribution is lost for good.
      ad_id:       referral.ad_id ?? null,
      ad_ref:      referral.ref ?? null,
      ts:          ev.timestamp,
    }});
  }
}

return out;
